        //      headers : {
        //        serviceId : 'HwmOvtSvc.findAllHwmOvtRept',
        //        viewId : me.getViewId(),
        //        scope : me
        //      },
        //      data : aprHistData.docData.afterchange,
        //      success : function(res, me) {
        //        if (res.errMsg != null) {
        //          Ext.Msg.alert("안내", res.errMsg);
        //          return;
        //        }
        //        //GO SANCTION POPUP
        //        var win = Ext.create('HwmOvtRept71', {
        //          command : Constants.sanction.DRAFT, // 신청
        //          aprHistData : BizComUtils.getApprovalFields(frmDetail),
        //        });
        //        me.mon(win, 'complete', function(records) {
        //          records.close();
        //          Ext.Msg.alert('알림', Messages.getMessage('I0000'), function(btn) {
        //            me.onPrevious('HwmOvtRept01');
