    /* 초기화 */
    onContainerInitialize: function(component, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            initialConfig = component.config,	// 초기데이터
            records = initialConfig.records,
            form = refs.frmDetail;

        me.setParentView(component.parentView);		// 부모 창

        vm.set('detail.id', Ext.id());
        vm.set('detail.crud', 'C');
        vm.set('detail.stcd', Constants.stcd.OUTSTANDING);
        vm.set('detail.aplDvcd', Constants.wrkAplDvcd.APPLY);
        vm.set('detail.aplDvcdNm', CodeUtils.getText('HWM009', vm.get('detail.aplDvcd')));
        vm.set('detail.aplStcd', Constants.aplStcd.PROGRESS_APPLY);

        vm.set('detail.hrHrpmCompId', SecurityUtils.getPrincipal().hrHrpmCompId); //회사
        vm.set('detail.hrHrpmEmpId', SecurityUtils.getPrincipal().hrHrpmEmpId);
        vm.set('detail.dpnm', SecurityUtils.getPrincipal().dpnm);
        vm.set('detail.empeNm', SecurityUtils.getPrincipal().empeNm);
        vm.set('detail.empePsitNm', SecurityUtils.getPrincipal().empePsitNm);
        vm.set('detail.rqpr', SecurityUtils.getPrincipal().hrHrpmEmpId + " / " + SecurityUtils.getPrincipal().dpnm + " / " + SecurityUtils.getPrincipal().empeNm + " / " + SecurityUtils.getPrincipal().empePsitNm);

        records.hrWrkmOvtApfName = DateUtils.parseDate(records.aplOvtStrdt) + '일 ' + DateUtils.getTimeFormat(records.aplOvtStrtm, 'H:i') + ' ~ ' + DateUtils.parseDate(records.aplOvtEdt) + '일 ' + DateUtils.getTimeFormat(records.aplOvtEdtm, 'H:i');
        vm.set('ovtApfInfo', records);
        refs.reptCntn.setReadOnly(false);

        form.setValues(vm.get('detail'));

        refs.aplOvtDt.setValue(DateUtils.parseDate(records.aplOvtDt));					// 일자
        refs.aplOvtStrdt.setValue(DateUtils.parseDate(records.aplOvtStrdt));			// 시작일자
        refs.aplOvtStrtm.setValue(DateUtils.parseTime(records.aplOvtStrtm.substr(0,4)));	// 시작시간
        refs.aplOvtEdt.setValue(DateUtils.parseDate(records.aplOvtEdt));				// 종료일자
        refs.aplOvtEdtm.setValue(DateUtils.parseTime(records.aplOvtEdtm.substr(0,4)));		// 종료시간
        refs.wrkStrdt.setValue(DateUtils.parseDate(records.aplOvtStrdt));			// 출근일자

        Ext.Ajax.request({
            headers : {
                serviceId : 'COMAPR0001R04',
                viewId : me.getViewId(),
                scope : me
            },
            jsonData : {
                aprHistId : records.comAprHistApfId
                // 결재이력ID
            },
            success : function(response) {
                var res = Ext.JSON.decode(response.responseText);
                if (res.result) {
                    var aprHistData = Ext.decode(res.result); //결재데이터
                    var docData = aprHistData.docData; // 문서데이터

                    //총 시간외근무시간 Visible 분기처리
                    if (!docData.afterchange || Ext.isEmpty(docData.afterchange.totOvtHodMonthHr) || Ext.isEmpty(docData.afterchange.totOvtHodWeekHr)) {
                        refs.ovtHodInfo.setHidden(true);
                    } else {
                        vm.set('ovtApfInfo.totOvtHodMonthHr', docData.afterchange.totOvtHodMonthHr);
                        vm.set('ovtApfInfo.totOvtHodWeekHr', docData.afterchange.totOvtHodWeekHr);
                    }
                }
            }
        });

        ApprovalBoxSvc.setup({
            command   : Constants.sanction.DRAFT,
            viewModel : vm,
            edocCd    : 'HwmOvtRept71',
            scope     : me
        });
    }

